 'editor-step':b=>{sync();editStep=+b.dataset.step;render();},mode:b=>{sync();mode=b.dataset.mode;preview=null;render();},
 'add-field':b=>{sync();const fs=b.dataset.parent!==undefined?(fieldAt(b.dataset.parent).field.children||=[]):d.definition.fields;fs.push(M.F('field_'+(fs.length+1),'新字段','text','input',{required:false}));render();},
 'remove-field':b=>{sync();const a=fieldAt(b.dataset.index);a.fs.splice(a.index,1);render();},
 'apply-fields':()=>{sync();M.validateFields(d.definition.fields);const migrated=d.records.map(r=>{const raw={...M.recordValues(d.definition.fields,r),...M.recordValues(d.applied_fields||d.definition.fields,r)};return M.ingest(d.definition,raw,M.defaultImport(d.definition.fields),state.files,r);});d.records=migrated;d.applied_fields=M.copy(d.definition.fields);d.definition.version++;d.mapping=M.defaultImport(d.definition.fields);preview=null;persist();notice='定义已应用。单条表单与导入模板共用这些字段。';editStep=1;render();},
 'infer-fields':()=>{if(d.records.length)throw Error('已有记录请先新建草稿');const rows=M.parseSource($('infer-source').value);d.definition.fields=M.infer(rows[0]);d.mapping=M.defaultImport(d.definition.fields);values=rows[0];sourceText=JSON.stringify(rows,null,2);preview=null;notice='已识别字段；请指定参考、来源编号和分组用途。';persist();render();},
 'add-item':b=>{sync();const f=fieldByValuePath(b.dataset.path);let a=valueAt(b.dataset.path);if(!a){let p=b.dataset.path.split('.'),o=page==='catalog-editor'?{spec:catalogDraft.spec}:values;for(const k of p.slice(0,-1))o=o[k]||(o[k]={});a=o[p.at(-1)]=[];}a.push(!f.item_type||f.item_type==='object'?Object.fromEntries((f.children||[]).map(c=>[c.key,c.type==='array'?[]:c.type==='object'?{}:''])):'');render();},
 'remove-item':b=>{sync();valueAt(b.dataset.path).splice(+b.dataset.index,1);render();},
 'new-record':()=>{sync();d.editing_id=null;d.pending_record=null;d.single_touched=false;values={};d.saved_form_signature=JSON.stringify(values);preview=null;render();},
 'preview-single':()=>{sync();const old=d.records.find(x=>x.sample_id===d.editing_id)||d.pending_record;preview=[M.ingest(d.definition,values,M.defaultImport(d.definition.fields),state.files,old)];const r=preview[0];d.pending_record={sample_id:r.sample_id,reference_id:r.reference_id,source_namespace:r.source_namespace};render();},
 'save-single':()=>{sync();const old=d.records.find(x=>x.sample_id===d.editing_id);const r=M.ingest(d.definition,values,M.defaultImport(d.definition.fields),state.files,old||d.pending_record);if(r.source_sample_id&&d.records.some(x=>x.sample_id!==r.sample_id&&(x.source_namespace||'default')===r.source_namespace&&x.source_sample_id===r.source_sample_id))throw Error('来源编号重复；请打开原记录编辑');if(old)d.records[d.records.indexOf(old)]=r;else d.records.push(r);d.editing_id=r.sample_id;d.pending_record=null;d.saved_form_signature=JSON.stringify(values);d.single_touched=false;preview=[r];notice='已保存。系统生成样本编号，参考按同一编号关联。';persist();render();},
 'edit-record':b=>{const r=d.records[+b.dataset.index];values={};for(const f of d.definition.fields)values[f.key]=f.role==='source'?r.source_sample_id:f.role==='group'?r.group_key:r[{input:'inputs',reference:'expected',metadata:'metadata'}[f.role]][f.key];d.editing_id=r.sample_id;d.pending_record=null;d.saved_form_signature=JSON.stringify(values);editStep=1;mode='single';render();},
 'detect-source':()=>{sync();const paths=safeSourcePaths();d.mapping.forEach(r=>{if(!paths.includes(r.source)){const f=d.definition.fields.find(x=>x.key===r.target);r.source=paths.find(p=>p===r.target||p===f?.label)||'';}const v=M.get(sourceRows()[0],r.source);if(['array','object'].includes(r.type)&&typeof v==='string')r.transform='json';});preview=null;persist();render();},
