 'commit-batch':()=>{sync();if(!preview||d.preview_signature!==JSON.stringify([sourceText,d.mapping,d.definition]))throw Error('内容或映射已变化，请重新预览');const signature=C.hash(JSON.stringify([sourceText,d.mapping,d.definition]));const prior=d.import_receipts?.find(r=>r.signature===signature);if(prior){notice='本批次已导入，返回原回执 '+prior.id;preview=null;editStep=2;persist();render();return;}const checked=M.inspectBatch(d.definition,sourceRows(),d.mapping,state.files,d.records);if(checked.records.length!==preview.length)throw Error('已保存数据发生变化，请重新预览');if(!preview.length)throw Error('没有可导入的有效行，请修复错误行');const receipt={id:M.uid('import'),signature,received:checked.total,accepted:preview.length,isolated:checked.errors.length,errors:M.copy(checked.errors),sample_ids:preview.map(r=>r.sample_id)};d.import_receipts||=[];d.import_receipts.push(receipt);d.records.push(...M.copy(preview));preview=null;notice='已保存 '+receipt.accepted+' 条候选；隔离 '+receipt.isolated+' 条错误行。原始行号和原因已保留。';editStep=2;persist();render();},
 'save-profile':()=>{sync();M.ingestBatch(d.definition,sourceRows(),d.mapping,state.files);state.importProfiles.push({id:M.uid('mapping'),name:d.name+' 导入方案',fields:M.copy(d.definition.fields),rules:M.copy(d.mapping)});persist();notice='导入方案已保存，后续选择即可复用。';render();},
 'download-template':()=>{sync();const raw={};for(const f of d.definition.fields)raw[f.key]=values[f.key]??'';download('数据导入模板.csv',M.csvWrite(d.definition.fields.map(f=>f.key),[raw]));},
 publish:()=>{sync();if(d.applied_fields&&JSON.stringify(d.applied_fields)!==JSON.stringify(d.definition.fields))throw Error('字段定义有未应用修改，请回①应用字段定义');if(!d.source?.trim()){editStep=0;render();throw Error('来源与依据：发布前请补充材料来源');}if((mode==='single'||d.single_touched)&&Object.keys(values).length&&JSON.stringify(values)!==d.saved_form_signature)throw Error('当前样本有未保存修改，请回②保存');if(mode==='single'&&editStep===1)throw Error('请先保存数据，再到③发布');const technical=$('dataset-technical')?.value,business=$('dataset-business')?.value;if(!technical||!business||technical===business)throw Error('请选择两个不同的确认身份');const v=M.publish(state,d);v.reviews=[{role:'technical',principal:technical,content_hash:v.content_hash},{role:'business',principal:business,content_hash:v.content_hash}];d=null;page=returnTask?'task':'assets';if(returnTask){task=state.tasks.find(x=>x.id===returnTask);task.dataset_id=v.version_id;task.asset_bindings||={};task.asset_bindings.reference_version_id=v.reference_version_id;returnTask=null;taskStep=1;}notice='已发布数据集 v'+v.version+(v.reference_version_id?' 与关联参考版本。':'；本次未创建参考资产。');persist();render();},
 'revise-data':b=>{const a=state.assets.find(x=>x.version_id===b.dataset.id),ref=state.assets.find(x=>x.version_id===a.reference_version_id);d=M.copy(a);d.reference_id=ref.id;d.applied_fields=M.copy(d.definition.fields);d.records.forEach(r=>{const rr=M.referenceFor(ref,r.sample_id);r.expected=M.copy(rr.expected);r.reference_id=rr.reference_id;});values={};sourceText='';editStep=2;page='editor';persist();render();},
