 'edit-connection':b=>{activeConnection=M.copy(state.connections.find(x=>x.version_id===b.dataset.id));render();},
 'clone-connection':b=>{activeConnection=M.copy(state.connections.find(x=>x.version_id===b.dataset.id));activeConnection.id=M.uid('connection');activeConnection.version=0;activeConnection.name+=' · 副本';render();},
