 'toggle-each':b=>{sync();const r=mappingRule(b.dataset.area,b.dataset.index);if(r.each)delete r.each;else {const fs=b.dataset.area==='import'?d.definition.fields:activeConnection.ports;const f=fs.find(x=>x.key===r.target);if(f?.type==='array'&&f.item_type&&f.item_type!=='object')throw Error('基础值列表请整组映射；逐项字段对应用于字段组列表');r.each=(f?.children||[M.F('value','值')]).map(f=>M.R(f.key,f.key,f.type,{required:f.required}));}preview=null;persist();render();},'add-item-map':b=>{mappingRule(b.dataset.area,b.dataset.index).each.push(M.R('','new_field','text',{required:false}));preview=null;render();},
