 'preview-connection':()=>{activeConnection.name=$('connection-name').value.trim();activeConnection.object_version=$('object-version').value.trim();activeConnection.returned=JSON.parse($('returned-json').value);const id=activeConnection.preview_dataset||activeConnection.demo_dataset_id,ds=C.entry(state,id),temp={...state,connections:[activeConnection]},t={connection_id:activeConnection.version_id,dataset_id:id,asset_bindings:C.defaultBindings(activeConnection,ds)};const {c,ref,errors}=C.resolve(temp,t);if(errors.length)throw Error(errors.join('\n'));const result=M.pipeline(c,ds.records[0],M.referenceFor(ref,ds.records[0].sample_id).expected,activeConnection.returned,state.files);$('connection-preview').innerHTML=humanValue(result);},
 'save-connection':()=>{actions['preview-connection']();activeConnection.name=$('connection-name').value.trim();activeConnection.object_version=$('object-version').value.trim();if(!activeConnection.name||!activeConnection.object_version)throw Error('补齐配置名称与对象版本');activeConnection.version=(Math.max(0,...state.connections.filter(x=>x.id===activeConnection.id).map(x=>x.version)))+1;activeConnection.version_id=activeConnection.id+'@'+activeConnection.version;state.connections.push(M.copy(activeConnection));activeConnection=null;notice='已保存新版本；旧任务继续使用旧映射。';persist();render();},
